// SINGLE-FILE build made by tools/build.mjs from the War Room sources. Needs only Node 18+.
// Checks a "GVT Player Export v1" file the way the War Room reads it, and says in plain words what to fix.
//   node tools/check-export.mjs export.json            a file
//   node tools/check-export.mjs 'https://…/export.json?key=…'   the live HQ link (read once, nothing is kept)
//   node tools/check-export.mjs --sample out.json [players]     writes a small made-up sample in the exact format
// Exit code 0 = ready, 1 = problems to fix, 2 = could not read the file. Same checker as the page (src/check.js).
import { readFileSync, writeFileSync } from 'node:fs';
import vm from 'node:vm';

const B64 = {"catalog.js":"","demo.js":"","engine.js":"","check.js":""};
const ctx = { console };
ctx.window = ctx; ctx.GVT = {};
vm.createContext(ctx);
for (const f of Object.keys(B64)) vm.runInContext(Buffer.from(B64[f], 'base64').toString('utf8'), ctx, { filename: f });
const G = ctx.GVT;

const argv = process.argv.slice(2);
if (argv[0] === '--sample') {
  const out = argv[1] || 'gvt-player-export-v1.sample.json', n = +(argv[2] || 40);
  const data = sample(G.demo(), n);
  writeFileSync(out, JSON.stringify(data, null, 1) + '\n');
  const r = G.check.run(JSON.parse(JSON.stringify(data)));
  console.log('wrote ' + out + ' (' + data.players.length + ' players, ' + data.sessions.length + ' sessions). ' + (r.ok ? 'It passes the checker.' : 'WARNING: it does not pass:\n' + G.check.text(r)));
  process.exit(r.ok ? 0 : 1);
}
if (!argv[0]) { console.log('usage: node tools/check-export.mjs <file.json | https://link> | --sample out.json [players]'); process.exit(2); }

let raw;
try {
  raw = /^https?:\/\//.test(argv[0]) ? await (await fetch(argv[0], { cache: 'no-store' })).text() : readFileSync(argv[0], 'utf8');
} catch (e) { console.log('Could not read ' + argv[0].replace(/([?&](key|k|token)=)[^&]+/gi, '$1…') + ': ' + e.message); process.exit(2); }
let obj;
try { obj = JSON.parse(raw); } catch (e) { console.log('NOT READY: this is not JSON (' + e.message + ').'); process.exit(1); }
const r = G.check.run(obj);
console.log(G.check.text(r));
process.exit(r.ok ? 0 : 1);

// a small sample: the first n made-up players who played, with their own sessions, purchases and notifications,
// re-numbered so every "p" points into the shorter list. The team testers are left out.
function sample(D, n) {
  const keep = [], map = new Map();
  const played = new Set(D.sessions.map(s => s.p));
  const buyers = new Set(D.buys.map(b => b.p));
  // a few buyers first, so the sample shows purchases, then players in order
  for (const i of [...buyers]) { if (keep.length >= Math.ceil(n / 5)) break; if (!/^GVT_Tester/.test(D.players[i].name)) keep.push(i); }
  for (let i = 0; i < D.players.length && keep.length < n; i++) if (played.has(i) && !keep.includes(i) && !/^GVT_Tester/.test(D.players[i].name)) keep.push(i);
  keep.sort((a, b) => a - b).forEach((i, k) => map.set(i, k));
  const re = x => ({ ...x, p: map.get(x.p) });
  return { v: 1, source: 'hq', asOf: D.asOf, day0: D.day0, days: D.days, adRate: D.adRate,
    players: keep.map(i => ({ ...D.players[i], uid: D.players[i].uid })),
    sessions: D.sessions.filter(s => map.has(s.p)).map(re),
    buys: D.buys.filter(b => map.has(b.p)).map(re),
    notifs: D.notifs.filter(t => map.has(t.p)).map(re) };
}
